node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});const page=await browser.newPage({viewport:{width:1280,height:800}});const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://localhost:3002');await page.locator('#start-button').click();await page.waitForTimeout(100);await page.keyboard.press('2');console.log('key2',await page.locator('.weapon .eyebrow').innerText());await page.keyboard.press('Escape');await page.locator('.weapon').click();console.log('tap',await page.locator('.weapon .eyebrow').innerText());await page.mouse.wheel(0,100);console.log('wheel',await page.locator('.weapon .eyebrow').innerText());await page.keyboard.down('w');await page.waitForTimeout(300);await page.keyboard.up('w');console.log('status',await page.locator('#health-label').textContent(),'errors',errors);await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
