node <<'NODE'
const {chromium}=require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{const b=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
for(const mobile of [false,true]){const context=await b.newContext({viewport:mobile?{width:390,height:844}:{width:1280,height:800},isMobile:mobile,hasTouch:mobile});const p=await context.newPage();const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto('http://localhost:3002');await p.locator('#start-button').click();await p.waitForTimeout(300);if(!mobile)await p.evaluate(()=>document.exitPointerLock());await p.locator('.weapon').click();const clicked=await p.locator('.weapon .eyebrow').innerText();await p.keyboard.press('1');const keyed=await p.locator('.weapon .eyebrow').innerText();await p.mouse.move(600,400);await p.mouse.wheel(0,100);const wheeled=await p.locator('.weapon .eyebrow').innerText();await p.keyboard.down('w');await p.waitForTimeout(250);await p.keyboard.up('w');console.log(JSON.stringify({mobile,clicked:clicked.split('\n')[0],keyed:keyed.split('\n')[0],wheeled:wheeled.split('\n')[0],taskCount:await p.locator('#task-count').textContent(),errors}));await context.close()}
await b.close()})().catch(e=>{console.error(e);process.exit(1)});
